function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const pools = [[1, 2, 4, 8, 16, 32, 64, 128, 256], [3, 5, 6, 9, 10, 12, 17, 24, 7, 11], null];
  const pool = pools[Math.floor(rand() * pools.length)];
  const pick = () => pool ? pool[Math.floor(rand() * pool.length)] : 1 + Math.floor(rand() * 256);
  const nums = Array.from({ length: n }, pick);
  if (rand() < 0.6) {
    // Build a sortable array: sort it, then shuffle inside each run of equal bit counts.
    nums.sort((a, b) => a - b);
    const bits = v => v.toString(2).split('1').length - 1;
    let start = 0;
    for (let i = 1; i <= n; i++) {
      if (i === n || bits(nums[i]) !== bits(nums[start])) {
        for (let j = i - 1; j > start; j--) {
          const k = start + Math.floor(rand() * (j - start + 1));
          [nums[j], nums[k]] = [nums[k], nums[j]];
        }
        start = i;
      }
    }
    // Sometimes swap one neighbouring pair, which may or may not break sortability.
    if (n > 1 && rand() < 0.4) {
      const p = Math.floor(rand() * (n - 1));
      [nums[p], nums[p + 1]] = [nums[p + 1], nums[p]];
    }
  }
  return [nums];
}
